new='''/** Polls until `check` holds, giving up after half a second so a red test reports instead of hanging. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Tears the given sockets and servers down, each server seeing its sockets close first so no close is logged late. */
export async function stopAll(openClients: WebSocket[], openServers: HalServer[]): Promise<void> {
  for (const client of openClients.splice(0)) client.terminate();
  for (const hal of openServers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  await stopAll(clients, servers);
}

